using System;
using System.IO;
using System.Linq;
using BuyBidBlow.Systems.Types;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
namespace BuyBidBlow.PlayerUISandbox.Editor {
[InitializeOnLoad] public static class MatchPlayVerification {
static MatchPlayVerification(){EditorApplication.update+=Update;}
static bool running=SessionState.GetBool("MatchPlayRunning",false);static double started=SessionState.GetFloat("MatchPlayStarted",0);
public static void RunBatch(){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Project/Dev/Sandbox/Interface/PlayerUI/SC_PlayerUI.unity");SessionState.SetBool("NotebookBatch",true);File.WriteAllText("Library/MatchPlay.request","play");}
static void Require(bool condition,string message){if(!condition)throw new Exception(message);}
static void Update(){if(!running){if(!File.Exists("Library/MatchPlay.request")||EditorApplication.isCompiling||EditorApplication.isUpdating)return;File.Delete("Library/MatchPlay.request");running=true;SessionState.SetBool("MatchPlayRunning",true);started=EditorApplication.timeSinceStartup;SessionState.SetFloat("MatchPlayStarted",(float)started);EditorApplication.isPlaying=true;return;}if(EditorApplication.timeSinceStartup-started>45){Finish("FAIL: Play initialization timeout");return;}if(!EditorApplication.isPlaying||EditorApplication.isCompiling)return;var b=UnityEngine.Object.FindFirstObjectByType<MatchUIBridge>();if(!b||b.Game==null)return;try{
Require(UnityEngine.Object.FindObjectsByType<BuyBidBlow.Props.AuctionEnvelopeDisplay>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length==1,"Single world envelope");var c=b.controller;c.body.linearVelocity=Vector3.zero;Capture(c,"LiveExplore");Physics.SyncTransforms();foreach(var station in UnityEngine.Object.FindObjectsByType<UIInteractionTarget>(FindObjectsSortMode.None).Where(t=>t.kind!=UIInteractionTarget.Kind.AuctionSeat)){Require(Physics.Raycast(station.transform.position+station.transform.forward*2,-station.transform.forward,out var hit,3,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore)&&hit.collider.GetComponentInParent<UIInteractionTarget>()==station,"Counter raycast "+station.kind);}Require(b.Game.Snapshot(b.Player).Cash==200,"Starting cash");b.ToggleInformation();Require(c.notebook.IsOpen&&c.notebook.cellValues.All(t=>t.text==""),"Empty notebook lock");c.notebook.Scroll(100);Require(c.notebook.FirstRound==10,"Notebook scroll end");b.ToggleInformation();Require(c.detection.enabled,"Notebook close restore");var target=UnityEngine.Object.FindObjectsByType<UIInteractionTarget>(FindObjectsSortMode.None).First(t=>t.kind==UIInteractionTarget.Kind.Straw);c.Open(target);Require(c.CurrentMode==PlayerUIController.Mode.Trade,"Trade mode lock");int price=b.Game.Price(Company.Straw);b.ConfirmTrade(0,0,1);Require(b.Game.Snapshot(b.Player).GetShares(Company.Straw)==1,"Live purchase");Require(c.hud.transform.Find("Assets - Top Left/Cash").GetComponent<Text>().text=="$"+(200-price),"Live HUD cash");Capture(c,"LiveTrade");b.ConfirmTrade(0,1,1);Require(b.Game.Snapshot(b.Player).Cash==200,"Live sale");b.ConfirmTrade(0,2,1);Require(b.Game.HasBet(b.Player),"Bet HUD");b.ConfirmTrade(0,2,1);c.Close();Require(c.detection.enabled,"Explore restore");b.AdvanceClock(60-b.Now);var seat=UnityEngine.Object.FindObjectsByType<UIInteractionTarget>(FindObjectsSortMode.None).First(t=>t.kind==UIInteractionTarget.Kind.AuctionSeat);c.Open(seat);b.Refresh();Require(c.auctionControls.activeSelf&&c.hud.transform.Find("Live Lot Details").gameObject.activeSelf,"Auction panels");Require(b.envelope&&b.envelope.firstRound==b.Game.Auction.Open.Lot.First.Round&&b.envelope.roundLabel.text.Contains(b.Game.Auction.Open.Lot.First.Round+"R"),"Envelope rounds");b.SubmitBid();Require(b.Game.Snapshot(b.Player).Reserved==1,"UI bid reservation");Capture(c,"LiveAuction");c.Close();Require(b.Game.Snapshot(b.Player).Reserved==1,"Exit keeps bid");b.AdvanceClock(60);Require(b.Game.Snapshot(b.Player).Cash==199,"Open charged");b.ToggleInformation();Require(b.OwnedInformation.Count==2&&c.notebook.cellValues.Count(t=>t.text!="")==4,"Awarded info only");Capture(c,"LiveNotebook");b.ToggleInformation();c.Open(seat);b.SubmitBid();b.SubmitBid(true);Require(b.Game.Snapshot(b.Player).Reserved==0,"Secret cancel");c.Close();b.AdvanceClock(10000);Require(b.Game.Complete&&b.privateInfo.transform.parent.gameObject.activeSelf,"Final standings view");Finish("PASS: actual Play startup, HUD cash, buy/sell, bet/cancel, trade lock/restore, auction panels, bid/exit/charge, secret cancel, final results. Notebook empty/owned cells, scrolling, lock/restore passed. No runtime exception during checks.");
}catch(Exception e){Debug.LogException(e);Finish("FAIL: "+e);}}
static void Capture(PlayerUIController c,string name){var canvas=c.hud.GetComponent<Canvas>();var mode=canvas.renderMode;var camera=canvas.worldCamera;float distance=canvas.planeDistance;var target=c.view.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(1920,1080,24);var tex=new Texture2D(1920,1080,TextureFormat.RGB24,false);try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=c.view;canvas.planeDistance=1;c.view.targetTexture=rt;Canvas.ForceUpdateCanvases();c.view.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1920,1080),0,0);tex.Apply();File.WriteAllBytes("Assets/Project/Dev/Sandbox/Interface/PlayerUI/"+name+".png",tex.EncodeToPNG());}finally{c.view.targetTexture=target;RenderTexture.active=active;canvas.renderMode=mode;canvas.worldCamera=camera;canvas.planeDistance=distance;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}static void Finish(string result){File.WriteAllText("Assets/Project/Dev/Sandbox/Interface/PlayerUI/MatchPlayVerification.txt",result);File.WriteAllText("Library/MatchPlay.result",result);running=false;SessionState.SetBool("MatchPlayRunning",false);EditorApplication.isPlaying=false;if(SessionState.GetBool("NotebookBatch",false)){SessionState.SetBool("NotebookBatch",false);EditorApplication.delayCall+=()=>EditorApplication.Exit(result.StartsWith("PASS")?0:1);}}
}
}